SELECT gen_random_uuid()::text, 'formula', '$y_h$', 'General Solution by Root Type', '$r_1 \ne r_2:\ C_1e^{r_1x} + C_2e^{r_2x};\quad r_1 = r_2:\ (C_1 + C_2x)e^{rx};\quad \alpha \pm j\beta:\ e^{\alpha x}(C_1\cos\beta x + C_2\sin\beta x)$', NULL, 'The homogeneous solution of a constant-coefficient equation, read from its characteristic roots.', '[{"symbol":"$r$","meaning":"roots of the characteristic equation"},{"symbol":"$C_1, C_2$","meaning":"arbitrary constants"}]'::jsonb, 'A root of multiplicity $m$ gives $e^{rx}, xe^{rx}, \ldots, x^{m-1}e^{rx}$.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Differential Equations' AND t."subject" = 'Mathematics' AND s."normKey" = 'higher-order with constant coefficients' AND s."active"), NULL, true, 'PENDING', now(), now()
