SELECT gen_random_uuid()::text, 'formula', '$W$', 'Wronskian', '$W(y_1, y_2) = y_1y_2'' - y_1''y_2$', NULL, 'Two solutions are independent exactly when their Wronskian is not zero.', '[{"symbol":"$y_1, y_2$","meaning":"two solutions of the homogeneous equation"}]'::jsonb, 'For $e^{r_1x}, e^{r_2x}$: $W = (r_2 - r_1)e^{(r_1 + r_2)x}$.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Differential Equations' AND t."subject" = 'Mathematics' AND s."normKey" = 'variation of parameters' AND s."active"), NULL, true, 'PENDING', now(), now()
