SELECT gen_random_uuid()::text, 'formula', '$x'''' - (\text{tr}\,A)x'' + (\det A)x = 0$', 'Reducing a 2×2 System to One Equation', '$x'' = ax + by,\ y'' = cx + dy \implies x'''' - (a + d)x'' + (ad - bc)x = 0$', NULL, 'Eliminate y to get one second-order equation; its characteristic roots are the eigenvalues.', '[{"symbol":"$a, b, c, d$","meaning":"the system''s coefficients"}]'::jsonb, '$\lambda^2 - (\text{trace})\lambda + \det = 0$.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Differential Equations' AND t."subject" = 'Mathematics' AND s."normKey" = 'systems of differential equations' AND s."active"), NULL, true, 'PENDING', now(), now()
